import { resolveLegacyBootMessage, type LegacyPlayerMessage } from '../legacy-runtime/legacyPlayerMessage';

/**
 * MAZER-UI-030: the one service worker problem that reaches the player's message toast.
 *
 * Decision 2026-11-14: remote sync stays silent and boot errors stay on the splash; the only new toast is "the offline
 * cache could not update". The worker is generated by Workbox (/app-sw.js), so it cannot post a custom message when its
 * precache download fails. The page sees the same event from the outside: the installing worker ends `redundant`
 * without ever reaching `installed`, or register()/update() rejects while the browser is online.
 *
 * The scene may not exist yet when this fires (the worker registers on window load), so the latest warning is held
 * and replayed to the first subscriber. One warning per page load.
 */
export const MAZER_SW_CACHE_WARNING_EVENT = 'mazer:sw-cache-warning' as const;

type CacheWarningListener = (message: LegacyPlayerMessage) => void;

const listeners = new Set<CacheWarningListener>();
let pending: LegacyPlayerMessage | null = null;
let reported = false;

/** Reports once per page load; later calls are ignored so a flapping worker cannot stack toasts. */
export const reportServiceWorkerCacheWarning = (technicalDetail?: string): boolean => {
  if (reported) {
    return false;
  }
  reported = true;
  const message = resolveLegacyBootMessage('service-worker-error', technicalDetail);
  if (listeners.size === 0) {
    pending = message;
    return true;
  }
  for (const listener of [...listeners]) {
    listener(message);
  }
  return true;
};

/** Replays a warning raised before the subscriber existed. Returns the unsubscribe function. */
export const subscribeServiceWorkerCacheWarning = (listener: CacheWarningListener): (() => void) => {
  listeners.add(listener);
  if (pending !== null) {
    const message = pending;
    pending = null;
    listener(message);
  }
  return () => {
    listeners.delete(listener);
  };
};

export const resetServiceWorkerCacheWarningForTests = (): void => {
  listeners.clear();
  pending = null;
  reported = false;
};

/** Registration/update rejections while offline are expected (airplane mode), not a cache problem. */
export const shouldWarnAboutServiceWorkerError = (online: boolean | undefined): boolean => online !== false;

interface InstallingWorkerLike {
  state: string;
  addEventListener: (type: 'statechange', listener: () => void) => void;
}

export interface InstallFailureRegistrationLike {
  installing?: InstallingWorkerLike | null;
  addEventListener?: (type: 'updatefound', listener: () => void) => void;
}

/**
 * Calls `onFailure` when a worker that was installing becomes `redundant` without having reached `installed`
 * (its precache download or activation failed). A worker replaced by a newer one has already reached `installed`,
 * so it does not count.
 */
export const watchServiceWorkerInstallFailure = (
  registration: InstallFailureRegistrationLike,
  onFailure: () => void
): void => {
  const watch = (worker: InstallingWorkerLike | null | undefined): void => {
    if (!worker) {
      return;
    }
    let reachedInstalled = false;
    worker.addEventListener('statechange', () => {
      if (worker.state === 'installed' || worker.state === 'activating' || worker.state === 'activated') {
        reachedInstalled = true;
      } else if (worker.state === 'redundant' && !reachedInstalled) {
        onFailure();
      }
    });
  };
  watch(registration.installing);
  registration.addEventListener?.('updatefound', () => watch(registration.installing));
};
